"""Rough, token-level guess at layers.15.mlp.down_proj component 2951.

This component is (almost exactly) one MLP hidden unit of layer 15: its activation is
dominated by that unit, which reads the residual stream in context. Its value is noisy and
mostly not a function of which token is present, so this program is only a weak sketch.

It says: the component is pushed negative by words of worked-out mathematical derivation
(connectives like "Therefore"/"Thus"/"So", and words like "factor", "express", "theorem",
"remainder") and by the "heading" colon-newline token, and pushed positive by
self-reflective words ("Wait", "Hmm", "Alternatively"). Every other token predicts 0.
"""

READS = ()

DERIVATION = {
    "Therefore", "Thus", "So", "so", "factor", "Factor", "express", "write",
    "theorem", "formula", "remainder", "quotient", "decomposition", "roots",
}
REFLECTIVE = {"Wait", "Hmm", "Alternatively", "Again"}
HEADING = {":\n\n"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    if tok in HEADING or word in DERIVATION:
        value = -0.6
    elif word in REFLECTIVE:
        value = 0.5
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP neuron 2958 (this component is almost exactly that neuron).

Its job is a sentence-start signal. In the middle of a sentence it sits near zero. Near the
start of a sentence it swings, and its strongest negative values come on the verb or copula
that follows the sentence's opening subject:
  - "It [is]", "This [is]", "There[’s]", "She [was]", "These [are]", "It’s [just]": about -1.1
  - the opening subject word itself ("It", "This", "They", ...): about -0.5
  - clause connectives that start a sentence ("However", "But", "So", "Thus", "Still"):
    mildly positive, about +0.3
Everything else is predicted as 0. This captures only a small part of the variance.
"""

READS = ()

SENTENCE_END = {".", "!", "?", "\n"}
SUBJECTS = {"It", "This", "That", "There", "These", "Those", "She", "He", "We", "They", "You", "I"}
PREDICATE_OPENERS = {
    "is", "are", "was", "were", "be", "am", "'s", "’s", "'re", "’re", "'m", "’m",
    "has", "have", "had", "will", "can", "would", "could", "should", "may", "might", "must",
    "just", "really", "simply", "only", "still", "always", "never", "not", "very",
}
CONNECTIVES = {"However", "But", "So", "Thus", "Therefore", "Still"}


def step(carry, prefix, upstream):
    # carry: (words since the sentence began, the sentence's first two words)
    tok = prefix.token_strings[-1].strip()
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    n, first = (0, ()) if carry is None or new_doc else carry
    value = 0.0
    if n == 0 and tok in SUBJECTS:
        value = -0.5
    elif n == 1 and first[0] in SUBJECTS and tok in PREDICATE_OPENERS:
        value = -1.1
    elif tok in CONNECTIVES:
        value = 0.3
    if tok in SENTENCE_END:
        next_carry = (0, ())
    else:
        next_carry = (n + 1, (first + (tok,))[:2])
    return next_carry, value

"""Layer 15 MLP hidden unit 2976, read through its down_proj component.

The component is essentially one hidden unit of the layer-15 MLP: its input
vector is about 0.55 on that unit and small elsewhere. The unit is quiet on
most text. It is busiest where the text is caught mid-phrase:

- a hard line wrap inside a sentence: a single newline right after a word,
  on a line that is already about 55 to 100 characters long, peaking at
  72 to 80 characters (where wrapped prose is cut by the editor);
- a Chinese, Japanese or Korean particle or verb ending that binds to the
  word before or after it (的 の 之 を に 了 する 를 을 ...);
- a closing quote, bracket or code backtick; a hyphen; a possessive 's.

Ordinary words sit near zero. Each kind of place gets its typical activation,
measured on training text. Only the line length is carried between tokens
(characters since the last newline, reset at each new document).
"""

import regex

READS = ()

PARTICLES = frozenset(["的", "の", "之", "を", "に", "了", "する", "して", "した", "る", "す", "た", "って", "의", "을", "를", "고"])
CLOSERS = frozenset(['"', "'", "”", "’", "`", ")", "）", "》", "」", "]", "()`", "`)"])
HYPHENS = frozenset(["-", "‐", "‑", "–"])
POSSESSIVES = frozenset(["'s", "'S", "’s", "’S"])
LINE_BREAKS = frozenset(["\n", " \n", "\r\n", " \r\n"])


def wrap_value(line_chars):
    """Activation at a newline after a word, given the characters on its line so far."""
    if line_chars < 55:
        return 0.4
    if line_chars < 72:
        return 1.4
    if line_chars <= 80:
        return 2.5
    if line_chars < 100:
        return 1.7
    return 0.6


def kind_value(tok):
    """Typical activation for a token that is not a line break."""
    if tok in PARTICLES:
        return 1.8
    if tok in CLOSERS:
        return 0.7
    if tok in HYPHENS:
        return 0.46
    if tok in POSSESSIVES:
        return 0.37
    if tok in (",", "."):
        return 0.15
    if regex.fullmatch(r"\s*\p{Han}+", tok):
        return 0.01
    if regex.fullmatch(r"\s?\p{L}+", tok):
        return 0.035
    if regex.fullmatch(r"\s?\d+", tok):
        return 0.10
    if tok.strip() == "":
        return 0.15
    if not regex.search(r"[\p{L}\p{N}]", tok):
        return 0.13
    return 0.09


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    line_chars, doc = carry if carry is not None else (0, None)
    if prefix.document_ids[-1] != doc:  # a new document starts a new line
        line_chars, doc = 0, prefix.document_ids[-1]
    if "\n" in tok or "\r" in tok:
        if tok in LINE_BREAKS and regex.search(r"[\p{L}\p{N}]$", prev):
            value = wrap_value(line_chars)
        else:
            value = 0.15
        line_chars = 0
    else:
        line_chars += len(tok)
        value = kind_value(tok)
    return (line_chars, doc), float(value)

"""A rough, token-level guess at layers.15.mlp.down_proj component 2978.

The component is diffuse: its activation (std 0.8) is spread over thousands of MLP hidden
units, and no token class, position or short context explains much of it. This program
keeps only the few patterns that the data shows, each a plain concept:

- the first token of a document: about 0 (the component is silent there);
- chat and tool-call markup (role names, <think>, <tool_call>...): clearly positive;
- code operators (&&, ::, ^, **, import): negative;
- digits and whitespace: mildly positive;
- everything else: the average, about 0.06.

Rules are fitted on about 2,000 training rows and explain well under 1% of the variance.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

CHAT_MARKUP = {
    "<|im_start|>", "<|im_end|>", "<think>", "</think>", "<tool_call>", "</tool_call>",
    "<tool_response>", "</tool_response>", "assistant", "user",
}
CODE_OPERATORS = {"&&", "||", "::", "->", "=>", "^", "**", "import"}


def step(carry, prefix, upstream: Mapping):
    # The first token of each document starts a new context: the component is silent there.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    token = prefix.token_strings[-1]
    bare = token.strip()
    if token in CHAT_MARKUP:
        value = 0.25
    elif bare in CODE_OPERATORS:
        value = -0.1
    elif bare.isdigit() or bare == "" or token.isspace():
        value = 0.11
    else:
        value = 0.065
    return carry, value

"""Coarse token-class means. The component's activation is close to zero on average and
varies diffusely; the only signal is a slight lean positive on words and digits, and a
slight lean negative on whitespace and punctuation. These means are small and explain
almost none of the variance."""
import regex
from collections.abc import Mapping

READS: tuple[str, ...] = ()

MEANS = {
    "word_sp": 0.0001, "word_nosp": 0.0212, "digits": 0.0059, "punct_sym": -0.0025,
    "space": -0.0088, "han": 0.0009, "kana": 0.0324, "cyrillic": 0.0086, "other": 0.0196,
}


def token_class(s: str) -> str:
    t = s.strip()
    if not t:
        return "space"
    if regex.fullmatch(r"\p{Han}+", t):
        return "han"
    if regex.search(r"[\p{Hiragana}\p{Katakana}]", t):
        return "kana"
    if regex.search(r"\p{Cyrillic}", t):
        return "cyrillic"
    if regex.fullmatch(r"\p{N}+", t):
        return "digits"
    if regex.fullmatch(r"[A-Za-z]+", t):
        return "word_sp" if s[:1] == " " else "word_nosp"
    if regex.fullmatch(r"\p{P}+|\p{S}+", t):
        return "punct_sym"
    return "other"


def step(carry, prefix, upstream: Mapping):
    return carry, MEANS[token_class(prefix.token_strings[-1])]

"""Layer 15 MLP down-projection, component 2996: the biography-header detector.

What it does: this component goes strongly negative on the opening parenthesis of an
encyclopedia-style entry, the "(" right after a title or bare name at the start of a
document, as in "Stefan Milošević (footballer, born ...)" or "Edward Marsland (18 May ...".
It is also strongly negative on "born" in that opening, mildly negative through the rest of
that lead sentence (dates, ")", commas, "is"), and near zero elsewhere. A small positive
response goes to permission verbs (let, allow, permit).

The rule, in plain terms:
  - a document's opening is the first ~24 tokens after its start, if they contain no digits;
  - the opening is a "title" if it is short, on one line, has a capital letter and no
    ordinary sentence words (the, is, of, and, ...);
  - "(" in a title opening: -42; "born" in an opening: -35;
  - other "(" / ")" / dashes in an opening: about -5 to -10 (only when not a title);
  - after a title "(", the rest of the sentence up to its end: -3 per token (-15 on ")", -6 on
    "," and " is").
"""

import re

READS = ()

OPENING = 24
LEAD = -3.0
LEAD_TOKENS = {")": -15.0, ",": -6.0, " is": -6.0}
SENTENCE_WORDS = re.compile(
    r"\b(the|a|an|is|was|are|were|be|been|has|have|had|of|in|on|at|to|and|or|with|by|"
    r"for|from|as|that|it|he|she|they|this|which|who|not)\b"
)
TITLE_OPENING = {
    " (": -42.0, "born": -35.0, " born": -35.0, " —": -10.0, ")": -7.0, ",": -6.0, " is": -6.0,
}
OTHER_OPENING = {
    " (": -8.0, "born": -30.0, " born": -30.0, ")": -10.0, " also": -10.0, " known": -10.0,
    " —": -5.0,
}
PERMISSION = {
    " let", " lets", " letting", " allow", " allows", " allowed", " allowing", " permit",
}


def is_title(text):
    """A short one-line opening with a capital letter and no ordinary sentence words."""
    return (
        len(text) < 80
        and "\n" not in text
        and bool(re.search(r"[A-Z]", text))
        and not SENTENCE_WORDS.search(text)
    )


def step(carry, prefix, upstream):
    # carry: (position where the document began, digits seen, text of its opening, in lead)
    start, digits, text, lead = carry if carry else (0, False, "", False)
    t = prefix.position
    tok = prefix.token_strings[-1]
    if t > 0 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        start, digits, text, lead = t, False, "", False
    value = 0.0
    opening = 1 <= t - start < OPENING and not digits
    if opening:
        title = is_title(text)
        value = (TITLE_OPENING if title else OTHER_OPENING).get(tok, 0.0)
        if tok == " (" and title:
            lead = True
    elif lead:
        value = LEAD_TOKENS.get(tok, LEAD)
        if tok.strip() in (".", "!", "?") or "\n" in tok:
            lead = False
    elif tok in PERMISSION:
        value = 4.0
    if any(ch.isdigit() for ch in tok):
        digits = True
    if t - start < OPENING:
        text += tok
    return (start, digits, text, lead), value

"""Be-verb detector for layers.15.mlp.down_proj component 3005.

The component is a "predicate is coming" signal. It is large on forms of the
verb "be" (is, was, are, were, be, been, being, am, and their translations)
when the be-form opens a predicate: a passive ("is used", "was found") or a
predicative ("is a", "are the"). Modal + be ("can be", "must be") and "has
been" are strongest. After an expletive subject ("there was", "this is") it is
weak. An adverb directly after a be-form ("is not", "was also", "is usually")
carries a smaller copy of the signal. Everything else is about 0.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

BE = {"is", "was", "are", "were", "be", "been", "being", "am",
      "est", "ist", "sind", "ser", "es", "é", "è", "são", "foi", "sono", "sont",
      "fost", "fue", "été", "être", "war", "wird", "wurde", "sein"}
CONTRACTED_BE = {"'m", "'re", "’re"}
IT_S = {"'s", "’s"}
MODALS = {"can", "will", "must", "may", "should", "would", "could", "might", "been", "has", "have"}
EXPLETIVES = {"there", "this"}
ADVERBS = {"not", "also", "then", "now", "actually", "just", "already", "still",
           "always", "often", "only", "even", "very", "ever"}


def step(carry, prefix, upstream: Mapping):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    whole = raw.startswith(" ")  # a token that starts a word, not a piece of one
    prev_raw = prefix.token_strings[-2] if prefix.position > 0 else ""
    prev = prev_raw.strip().lower()
    if (whole and word in BE) or raw in CONTRACTED_BE:
        if prev in MODALS:
            value = 15.0
        elif prev in EXPLETIVES:
            value = 4.0
        else:
            value = 12.0
    elif raw in IT_S and prev in {"it", "that", "there"}:
        value = 5.0
    elif whole and (prev in BE or prev_raw in CONTRACTED_BE):
        value = 7.0 if word in ADVERBS or word.endswith("ly") else 0.0
    else:
        value = 0.0
    return carry, value
